	if err != nil {
		logging.Warn(logCtx, "failed to mark session ended",
			slog.String("error", err.Error()))
		return nil
	}
	if ended {
		sessionEndCondenseSpawn(worktreeRoot, event.SessionID)
	}

	return nil
